import {sceneTemplates,loadCharacters,saveCharacters,selectionSnapshot} from './story-resources.js';
export function createResourcePicker(root,onChange){
 let people=[],selection={sceneId:'cafe',casting:[]},editing=null,storage;
 root.innerHTML=`<h2>选择故事场景与人物</h2><p class="hint">复用未来校园的六个区域。生成故事目前在二维地图试玩，尚未自动投放 3D 校园。</p><label>故事场景<select id="resource-scene"></select></label><p id="resource-description"></p><div id="resource-cast"></div><details id="resource-library"><summary>管理人物库</summary><p class="hint">档案供新故事复用；保存过的故事保留当时的人物。新增人物暂用二维通用形象，不自动创建 3D 模型。</p><label>人物档案<select id="resource-person"></select></label><button type="button" id="resource-new">新增人物</button><label>英文姓名<input id="resource-name" maxlength="60"></label><label>固定身份<input id="resource-identity" maxlength="200"></label><label>性格与说话特点<textarea id="resource-personality" maxlength="200" style="min-height:70px"></textarea></label><button type="button" id="resource-save">保存人物</button><button type="button" id="resource-archive">停用人物</button></details><p id="resource-status" role="status"></p>`;
 const $=id=>root.querySelector('#resource-'+id),notice=t=>$('status').textContent=t;
 try{storage=localStorage;people=loadCharacters(storage);}catch(e){notice('人物库无法读取：'+e.message);root.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true);return {snapshot(){throw Error('人物库不可用');},getSelection:()=>selection,restore(){}};}
 for(const s of sceneTemplates)$('scene').add(new Option(s.name,s.id));
 function defaults(id){const s=sceneTemplates.find(x=>x.id===id);selection={sceneId:id,casting:s.cast.map((characterId,i)=>({characterId,role:s.roles[i]}))};}
 function renderCast(){const s=sceneTemplates.find(x=>x.id===selection.sceneId);$('scene').value=s.id;$('description').textContent=s.description;$('cast').replaceChildren();for(let i=0;i<3;i++){const row=document.createElement('div');row.className='resource-cast-row';const label=document.createElement('label');label.textContent=i===0?'委托人':i===1?'互动人物':'第三位人物（选填）';const select=document.createElement('select');select.setAttribute('aria-label',label.textContent);select.add(new Option('请选择',''));for(const p of people.filter(p=>!p.archived))select.add(new Option(p.name+' · '+p.identity,p.id));select.value=selection.casting[i]?.characterId||'';label.append(select);const roleLabel=document.createElement('label');roleLabel.textContent='本故事职责';const role=document.createElement('input');role.maxLength=200;role.value=selection.casting[i]?.role||'';role.setAttribute('aria-label','人物 '+(i+1)+' 的故事职责');roleLabel.append(role);const update=()=>{selection.casting[i]={characterId:select.value,role:role.value};onChange();};select.onchange=update;role.oninput=update;row.append(label,roleLabel);$('cast').append(row);}}
 function editor(id){editing=id;const p=people.find(x=>x.id===id);for(const key of ['name','identity','personality'])$(key).value=p?.[key]||'';$('archive').disabled=!p;$('archive').textContent=p?.archived?'启用人物':'停用人物';}
 function renderPeople(){const id=editing;$('person').replaceChildren();for(const p of people)$('person').add(new Option(p.name+(p.archived?'（已停用）':''),p.id));$('person').value=id||people[0]?.id;editor($('person').value);}
 $('scene').onchange=()=>{defaults($('scene').value);renderCast();onChange();};$('person').onchange=()=>editor($('person').value);
 $('new').onclick=()=>{editor(null);$('person').selectedIndex=-1;$('name').focus();};
 $('save').onclick=()=>{try{const old=people.find(p=>p.id===editing);const p={...old,id:editing||'custom-'+crypto.randomUUID(),name:$('name').value.trim(),identity:$('identity').value.trim(),personality:$('personality').value.trim(),archived:old?.archived||false};const next=people.filter(x=>x.id!==p.id).concat(p);saveCharacters(storage,next);people=next;editing=p.id;renderPeople();renderCast();onChange();notice('人物已保存，可用于其他故事。');}catch(e){notice('未保存：'+e.message);}};
 $('archive').onclick=()=>{try{const next=people.map(p=>p.id===editing?{...p,archived:!p.archived}:p);saveCharacters(storage,next);people=next;renderPeople();renderCast();onChange();notice('人物状态已更新，已保存的故事不受影响。');}catch(e){notice('未保存：'+e.message);}};
 defaults('cafe');renderCast();renderPeople();
 return {snapshot:()=>selectionSnapshot(selection.sceneId,selection.casting,people),getSelection:()=>structuredClone(selection),restore(raw){if(raw&&sceneTemplates.some(s=>s.id===raw.sceneId)&&Array.isArray(raw.casting)){selection=structuredClone(raw);renderCast();}}};
}
